#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_SIZE 200

#define MAX(a,b) ((a) > (b) ? (a) : (b))

/** 链表节点 **/
typedef struct ListNode {
    int v; // 目标点
    int w; // 出发点到达目标点的耗时
    struct ListNode *next;
} ListNode;

/** 链表 **/
typedef struct LinkedList {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

/** 初始化链表 **/
LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));
    link->head = NULL;
    link->tail = NULL;
    link->size = 0;
    return link;
}

/** 链表尾插 **/
void add_LinkedList(LinkedList *link, int v, int w) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));
    node->v = v;
    node->w = w;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

// 记录源点到其他各点的最短耗时
int dist[MAX_SIZE];

int cmp(const void* a, const void* b) {
    int A = *((int*) a);
    int B = *((int*) b);
    return dist[B] - dist[A];
}

int main() {
    int n;
    scanf("%d", &n);

    LinkedList **graph = (LinkedList **) calloc(n + 1, sizeof(LinkedList *));

    int m;
    scanf("%d", &m);

    for (int i = 0; i < m; i++) {
        // 出发点, 目标点, 出发点到达目标点的耗时
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);

        if (graph[u] == NULL) {
            graph[u] = new_LinkedList();
        }

        add_LinkedList(graph[u], v, w);
    }

    // 初始时，假设源点不可达其他剩余点，即源点到达其他点的耗时无限大
    for (int i = 1; i <= n; i++) {
        dist[i] = INT_MAX;
    }

    // 源点
    int src;
    scanf("%d", &src);

    // 源点到达源点的耗时为0
    dist[src] = 0;

    // needCheck中记录的其实是：已被探索过的路径的终点（路径指的是源点->终点）
    // 排序规则是，路径终点的权重（即源点->终点的耗时）越小越靠后
    int needCheck[MAX_SIZE];
    int needCheck_size = 0;

    // 初始被探索过的路径只有源点本身
    needCheck[0] = src;
    needCheck_size++;

    // 记录对应点是否在needCheck中
    int visited[n + 1];
    for (int i = 1; i <= n; i++) {
        visited[i] = 0;
    }
    visited[src] = 1;

    while (needCheck_size > 0) {
        // 取出最优路径的终点（耗时最少的路径）作为新的起点
        int cur = needCheck[needCheck_size - 1];
        needCheck_size--;
        visited[cur] = 0;

        // 如果cur有可达的其他点
        if(graph[cur] != NULL) {
            ListNode* node = graph[cur]->head;
            while(node != NULL) {
                int v = node->v; // v是可达的其他店
                int w = node->w; // w是cur->v的耗时

                // 那么如果从源点到cur点的耗时是dist[cur]，那么源点到v点的耗时就是dist[cur] + w
                int newDist = dist[cur] + w;

                // 而源点到v的耗时之前是dist[v]，因此如果newDist < dist[v]，则找到更少耗时的路径
                if(dist[v] > newDist) {
                    // 更新源点到v的路径，即更新v点权重
                    dist[v] = newDist;
                    // 如果v点不在needCheck中，则加入，因为v作为终点的路径需要加入到下一次最优路径的评比中
                    if(!visited[v]) {
                        visited[v] = 1;
                        needCheck[needCheck_size] = v;
                        needCheck_size++;
                        qsort(needCheck, needCheck_size, sizeof(int), cmp);
                    }
                }

                node = node->next;
            }
        }
    }

    int ans = 0;
    for(int i=1; i<=n; i++) {
        ans = MAX(ans, dist[i]);
    }

    printf("%d\n", ans == INT_MAX ? -1 : ans);

    return 0;
}
